/* AIVIC_FUNCTION_BUNDLE_START owner=consolidateAndDeduplicateImprovementTasks exports=consolidateAndDeduplicateImprovementTasks */
const __aivicBundle_34_consolidateAndDeduplicateImprovementTasks = (() => {
  function consolidateAndDeduplicateImprovementTasks(
    tasks: Array<{ id: string; name: string; effort: number; impact: number }>
  ): any {
    const totalBefore = tasks.length;
  
    if (totalBefore === 0) {
      return [];
    }
  
    const consolidatedMap = new Map<
      string,
      { id: string; name: string; effort: number; impact: number; linkedTaskIds: string[] }
    >();
  
    const normalizeTaskName = (name: string): string => {
      return name
        .toLowerCase()
        .trim()
        .replace(/\s+/g, ' ')
        .replace(/[^\w\s]/g, '');
    };
  
    const nameToCanonicalId = new Map<string, string>();
  
    for (const task of tasks) {
      const normalizedName = normalizeTaskName(task.name);
  
      if (!nameToCanonicalId.has(normalizedName)) {
        nameToCanonicalId.set(normalizedName, task.id);
        consolidatedMap.set(task.id, {
          id: task.id,
          name: task.name,
          effort: task.effort,
          impact: task.impact,
          linkedTaskIds: [task.id],
        });
      } else {
        const canonicalId = nameToCanonicalId.get(normalizedName)!;
        const existing = consolidatedMap.get(canonicalId)!;
  
        if (!existing.linkedTaskIds.includes(task.id)) {
          existing.linkedTaskIds.push(task.id);
        }
  
        existing.effort = Math.max(existing.effort, task.effort);
        existing.impact = Math.max(existing.impact, task.impact);
      }
    }
  
    const consolidatedTasks = Array.from(consolidatedMap.values());
    const totalAfter = consolidatedTasks.length;
    const consolidationRate =
      totalBefore > 0 ? Math.round(((totalBefore - totalAfter) / totalBefore) * 100) : 0;
  
    return {
      consolidatedTasks,
      totalBefore,
      totalAfter,
      consolidationRate,
    };
  }
  return { consolidateAndDeduplicateImprovementTasks };
})();
export const consolidateAndDeduplicateImprovementTasks = __aivicBundle_34_consolidateAndDeduplicateImprovementTasks.consolidateAndDeduplicateImprovementTasks;
/* AIVIC_FUNCTION_BUNDLE_END owner=consolidateAndDeduplicateImprovementTasks */

