const __aivicBundle_42_sortImprovementProposalsByScore = (() => {
  function sortImprovementProposalsByScore(
    proposals: Array<{
      proposal_id?: string;
      proposalId?: string;
      proposal_title?: string;
      proposalName?: string;
      comprehensive_score?: number;
      score?: number;
      expectedAccuracyImprovement?: number;
      expectedSatisfactionLift?: number;
      estimatedImplementationHours?: number;
      implementationRiskLevel?: 'low' | 'medium' | 'high';
      business_value_score?: number;
      technical_difficulty_score?: number;
      user_impact_score?: number;
    }>
  ): Array<{
    proposal_id?: string;
    proposalId?: string;
    proposal_title?: string;
    proposalName?: string;
    comprehensive_score?: number;
    score?: number;
    rank?: number;
  }> {
    if (!proposals || proposals.length === 0) {
      return [];
    }
  
    const proposalsWithScore = proposals.map((proposal) => {
      let score: number;
  
      if (proposal.comprehensive_score !== undefined) {
        score = proposal.comprehensive_score;
      } else if (
        proposal.expectedAccuracyImprovement !== undefined &&
        proposal.expectedSatisfactionLift !== undefined &&
        proposal.estimatedImplementationHours !== undefined &&
        proposal.implementationRiskLevel !== undefined
      ) {
        const accuracyWeight = 0.35;
        const satisfactionWeight = 0.35;
        const implementationWeight = 0.3;
  
        const riskMultiplier =
          proposal.implementationRiskLevel === 'low'
            ? 1.0
            : proposal.implementationRiskLevel === 'medium'
              ? 0.85
              : 0.7;
  
        const implementationScore = Math.max(
          0,
          100 - (proposal.estimatedImplementationHours / 200) * 100
        );
  
        score =
          (proposal.expectedAccuracyImprovement * accuracyWeight +
            proposal.expectedSatisfactionLift * satisfactionWeight +
            implementationScore * implementationWeight) *
          riskMultiplier;
      } else {
        score = 0;
      }
  
      return {
        ...proposal,
        comprehensive_score:
          proposal.comprehensive_score !== undefined
            ? proposal.comprehensive_score
            : score,
        score: score,
      };
    });
  
    const sorted = proposalsWithScore.sort((a, b) => {
      const scoreA = a.comprehensive_score ?? a.score ?? 0;
      const scoreB = b.comprehensive_score ?? b.score ?? 0;
  
      if (scoreB !== scoreA) {
        return scoreB - scoreA;
      }
  
      const idA = a.proposal_id ?? a.proposalId ?? '';
      const idB = b.proposal_id ?? b.proposalId ?? '';
      return idA.localeCompare(idB);
    });
  
    return sorted.map((proposal, index) => ({
      proposal_id: proposal.proposal_id,
      proposalId: proposal.proposalId,
      proposal_title: proposal.proposal_title,
      proposalName: proposal.proposalName,
      comprehensive_score: proposal.comprehensive_score,
      score: proposal.score,
      rank: index + 1,
    }));
  }
  return { sortImprovementProposalsByScore };
})();
