/* AIVIC_FUNCTION_BUNDLE_START owner=calculateAndRankImprovementProposals exports=calculateAndRankImprovementProposals */
const __aivicBundle_43_calculateAndRankImprovementProposals = (() => {
  function calculateAndRankImprovementProposals(input: any): any {
    const proposals = input.proposals || [];
  
    if (!Array.isArray(proposals) || proposals.length === 0) {
      return { ranked_proposals: [] };
    }
  
    // Calculate overall_score for each proposal based on three dimensions
    const scoredProposals = proposals.map((proposal: any) => {
      const kpiScore = proposal.kpi_contribution_score ?? 0;
      const difficultyScore = proposal.implementation_difficulty_score ?? 0;
      const impactScore = proposal.user_impact_score ?? 0;
  
      // Normalize scores to 0-100 range
      const normalizedKpi = Math.min(100, Math.max(0, kpiScore));
      const normalizedDifficulty = Math.min(100, Math.max(0, difficultyScore));
      const normalizedImpact = Math.min(100, Math.max(0, impactScore));
  
      // Higher difficulty reduces score; lower difficulty increases it
      const difficultyFactor = 100 - normalizedDifficulty;
  
      // Weighted average: KPI contribution (40%), implementation difficulty inverse (30%), user impact (30%)
      const overallScore =
        normalizedKpi * 0.4 + difficultyFactor * 0.3 + normalizedImpact * 0.3;
  
      return {
        proposal_id: proposal.proposal_id,
        title: proposal.title,
        kpi_contribution_score: kpiScore,
        implementation_difficulty_score: difficultyScore,
        user_impact_score: impactScore,
        overall_score: Math.round(overallScore),
      };
    });
  
    // Sort by overall_score descending
    const sortedProposals = scoredProposals.sort(
      (a: any, b: any) => b.overall_score - a.overall_score
    );
  
    // Assign rank and determine deployment phase
    const rankedProposals = sortedProposals.map((proposal: any, index: number) => {
      const rank = index + 1;
      let recommendedDeploymentPhase: 'immediate' | 'next_sprint' | 'backlog';
  
      if (proposal.overall_score >= 70) {
        recommendedDeploymentPhase = 'immediate';
      } else if (proposal.overall_score >= 40) {
        recommendedDeploymentPhase = 'next_sprint';
      } else {
        recommendedDeploymentPhase = 'backlog';
      }
  
      return {
        ...proposal,
        rank,
        recommendedDeploymentPhase,
      };
    });
  
    return {
      ranked_proposals: rankedProposals,
    };
  }
  return { calculateAndRankImprovementProposals };
})();
export const calculateAndRankImprovementProposals = __aivicBundle_43_calculateAndRankImprovementProposals.calculateAndRankImprovementProposals;
/* AIVIC_FUNCTION_BUNDLE_END owner=calculateAndRankImprovementProposals */

