/* AIVIC_FUNCTION_BUNDLE_START owner=attemptAddProposalToRoadmap exports=attemptAddProposalToRoadmap */
const __aivicBundle_54_attemptAddProposalToRoadmap = (() => {
  function attemptAddProposalToRoadmap(proposal: any): {
    additionAttempted: boolean;
    additionSuccessful: boolean;
    roadmapPosition: string | null;
    failureReason: string | null;
    attemptTimestamp: string;
  } {
    const attemptTimestamp = new Date().toISOString();
  
    // Validate required fields for roadmap addition
    if (proposal.technicalFeasibilityEvaluation === null || proposal.technicalFeasibilityEvaluation === undefined) {
      throw new Error('技術実現性評価が不足しています。ロードマップへの組み込みには技術実現性評価が必須です。');
    }
  
    // Extract scoring inputs
    const businessValue = proposal.businessValue ?? 0;
    const technicalDifficulty = proposal.technicalDifficulty ?? 0;
    const userImpact = proposal.userImpact ?? 0;
    const technicalFeasibility = proposal.technicalFeasibilityEvaluation ?? 0;
  
    // Calculate composite priority score
    const priorityScore = (businessValue * 0.35) + (userImpact * 0.35) + ((100 - technicalDifficulty) * 0.2) + (technicalFeasibility * 0.1);
  
    // Minimum threshold for roadmap inclusion
    const minimumThreshold = 50;
  
    if (priorityScore < minimumThreshold) {
      return {
        additionAttempted: true,
        additionSuccessful: false,
        roadmapPosition: null,
        failureReason: 'Priority score below minimum threshold',
        attemptTimestamp,
      };
    }
  
    // Determine roadmap position based on priority score and technical feasibility
    let roadmapPosition: string;
  
    if (priorityScore >= 80 && technicalFeasibility >= 0.7) {
      roadmapPosition = 'Q1_Sprint_1';
    } else if (priorityScore >= 70 && technicalFeasibility >= 0.6) {
      roadmapPosition = 'Q1_Sprint_2';
    } else if (priorityScore >= 60 && technicalFeasibility >= 0.5) {
      roadmapPosition = 'Q2_Sprint_1';
    } else if (priorityScore >= 50 && technicalFeasibility >= 0.4) {
      roadmapPosition = 'Q2_Sprint_2';
    } else {
      roadmapPosition = 'Backlog';
    }
  
    return {
      additionAttempted: true,
      additionSuccessful: true,
      roadmapPosition,
      failureReason: null,
      attemptTimestamp,
    };
  }
  return { attemptAddProposalToRoadmap };
})();
export const attemptAddProposalToRoadmap = __aivicBundle_54_attemptAddProposalToRoadmap.attemptAddProposalToRoadmap;
/* AIVIC_FUNCTION_BUNDLE_END owner=attemptAddProposalToRoadmap */

