/* AIVIC_FUNCTION_BUNDLE_START owner=categorizeAndPrioritizeFailures exports=categorizeAndPrioritizeFailures */
const __aivicBundle_71_categorizeAndPrioritizeFailures = (() => {
  interface CategorizeAndPrioritizeFailuresRecord {
    id: string;
    reason_text: string;
    category: string | null;
  }
  
  interface CategorizeAndPrioritizeFailuresAggregatedStat {
    category: string;
    frequency_count: number;
    frequency_percentage: number;
    priority_rank: number;
    reasoning: string;
  }
  
  interface CategorizeAndPrioritizeFailuresResult {
    categorized_records: CategorizeAndPrioritizeFailuresRecord[];
    aggregated_stats: CategorizeAndPrioritizeFailuresAggregatedStat[];
    total_records: number;
  }
  
   function categorizeAndPrioritizeFailures(
    failureRecords: Array<{ id: string; reason_text: string; category: string | null }>,
    predefinedCategories: string[],
    categoryKeywords: Record<string, string[]>,
  ): CategorizeAndPrioritizeFailuresResult {
    const categorizedRecords: CategorizeAndPrioritizeFailuresRecord[] = [];
    const categoryFrequency: Record<string, number> = {};
  
    for (const category of predefinedCategories) {
      categoryFrequency[category] = 0;
    }
  
    for (const record of failureRecords) {
      let assignedCategory: string | null = null;
  
      for (const category of predefinedCategories) {
        const keywords = categoryKeywords[category] || [];
        const matchesKeywords = keywords.some((keyword) =>
          record.reason_text.includes(keyword),
        );
  
        if (matchesKeywords) {
          assignedCategory = category;
          categoryFrequency[category]++;
          break;
        }
      }
  
      categorizedRecords.push({
        id: record.id,
        reason_text: record.reason_text,
        category: assignedCategory,
      });
    }
  
    const aggregatedStats: CategorizeAndPrioritizeFailuresAggregatedStat[] = [];
    const totalRecords = failureRecords.length;
  
    for (const category of predefinedCategories) {
      const frequencyCount = categoryFrequency[category];
      const frequencyPercentage =
        totalRecords > 0 ? (frequencyCount / totalRecords) * 100 : 0;
  
      aggregatedStats.push({
        category,
        frequency_count: frequencyCount,
        frequency_percentage: frequencyPercentage,
        priority_rank: 0,
        reasoning: `Category: ${category}, Frequency: ${frequencyCount}, Percentage: ${frequencyPercentage}%`,
      });
    }
  
    aggregatedStats.sort((a, b) => {
      if (b.frequency_count !== a.frequency_count) {
        return b.frequency_count - a.frequency_count;
      }
      return a.category.localeCompare(b.category);
    });
  
    for (let i = 0; i < aggregatedStats.length; i++) {
      aggregatedStats[i].priority_rank = i + 1;
    }
  
    return {
      categorized_records: categorizedRecords,
      aggregated_stats: aggregatedStats,
      total_records: totalRecords,
    };
  }
  return { categorizeAndPrioritizeFailures };
})();
export const categorizeAndPrioritizeFailures = __aivicBundle_71_categorizeAndPrioritizeFailures.categorizeAndPrioritizeFailures;
/* AIVIC_FUNCTION_BUNDLE_END owner=categorizeAndPrioritizeFailures */

/* AIVIC_FUNCTION_BUNDLE_START owner=categorizeAndRankFailurePatterns exports=categorizeAndRankFailurePatterns */
const __aivicBundle_72_categorizeAndRankFailurePatterns = (() => {
  function categorizeAndRankFailurePatterns(
    patterns: Array<{
      pattern_id: string;
      category: string;
      occurrence_count: number;
      improvement_impact_data: any;
      user_satisfaction_impact: number;
      implementation_difficulty: number;
    }>,
  ): {
    categorizedRecords: Array<{
      recordId: string;
      rejectionReasonText: string;
      category: string;
      rejectedAt: string;
    }>;
    aggregationByCategory: Record<string, number>;
    classificationAccuracy: number;
    totalClassifiedRecords: number;
    classificationTimestamp: Date;
  } {
    if (!patterns || patterns.length === 0) {
      return {
        categorizedRecords: [],
        aggregationByCategory: {},
        classificationAccuracy: 1.0,
        totalClassifiedRecords: 0,
        classificationTimestamp: new Date(),
      };
    }
  
    for (const pattern of patterns) {
      if (pattern.improvement_impact_data === null || pattern.improvement_impact_data === undefined) {
        throw new Error('改善影響度データが不足しています');
      }
    }
  
    const aggregationByCategory: Record<string, number> = {};
    const categorizedRecords: Array<{
      recordId: string;
      rejectionReasonText: string;
      category: string;
      rejectedAt: string;
    }> = [];
  
    let successfulClassifications = 0;
  
    for (const pattern of patterns) {
      const category = pattern.category || 'unknown';
      const recordId = pattern.pattern_id;
      const rejectionReasonText = category;
      const rejectedAt = new Date().toISOString();
  
      categorizedRecords.push({
        recordId,
        rejectionReasonText,
        category,
        rejectedAt,
      });
  
      aggregationByCategory[category] = (aggregationByCategory[category] || 0) + 1;
      successfulClassifications++;
    }
  
    const classificationAccuracy =
      patterns.length > 0 ? successfulClassifications / patterns.length : 1.0;
  
    return {
      categorizedRecords,
      aggregationByCategory,
      classificationAccuracy,
      totalClassifiedRecords: patterns.length,
      classificationTimestamp: new Date(),
    };
  }
  return { categorizeAndRankFailurePatterns };
})();
export const categorizeAndRankFailurePatterns = __aivicBundle_72_categorizeAndRankFailurePatterns.categorizeAndRankFailurePatterns;
