/* AIVIC_FUNCTION_BUNDLE_START owner=evaluateNutritionImprovementProposal exports=evaluateNutritionImprovementProposal */
const __aivicBundle_73_evaluateNutritionImprovementProposal = (() => {
  function evaluateNutritionImprovementProposal(
    proposalData: any,
    criteria: any
  ): {
    is_approved: boolean;
    priority_score: number;
    evaluation_basis: {
      accuracy_improvement_rate_check: string;
      implementation_complexity_check: string;
      operational_load_check: string;
      total_score_check: string;
    };
    rationale: string;
  } {
    const accuracyImprovement = proposalData.expected_accuracy_improvement_rate ?? 0;
    const implementationComplexity = proposalData.implementation_complexity_score ?? 0;
    const operationalLoad = proposalData.operational_load_score ?? 0;
    
    
  
    const minAccuracyThreshold = criteria.min_accuracy_improvement_rate ?? 0;
    const maxComplexityThreshold = criteria.max_implementation_complexity_score ?? 100;
    const maxOperationalLoadThreshold = criteria.max_operational_load_score ?? 100;
    const approvalThresholdScore = criteria.approval_threshold_score ?? 60;
  
    const accuracyCheck = accuracyImprovement >= minAccuracyThreshold ? 'PASS' : 'FAIL';
    const complexityCheck = implementationComplexity <= maxComplexityThreshold ? 'PASS' : 'FAIL';
    const operationalCheck = operationalLoad <= maxOperationalLoadThreshold ? 'PASS' : 'FAIL';
  
    const accuracyScore = Math.min(100, Math.max(0, (accuracyImprovement / 25) * 100));
    const complexityScore = Math.max(0, 100 - (implementationComplexity / maxComplexityThreshold) * 100);
    const operationalScore = Math.max(0, 100 - (operationalLoad / maxOperationalLoadThreshold) * 100);
  
    const priorityScore = Math.round(
      accuracyScore * 0.35 + complexityScore * 0.35 + operationalScore * 0.3
    );
  
    const totalScoreCheck = priorityScore >= approvalThresholdScore ? 'PASS' : 'FAIL';
  
    const isApproved =
      accuracyCheck === 'PASS' &&
      complexityCheck === 'PASS' &&
      operationalCheck === 'PASS' &&
      totalScoreCheck === 'PASS';
  
    const evaluationBasis = {
      accuracy_improvement_rate_check: accuracyCheck,
      implementation_complexity_check: complexityCheck,
      operational_load_check: operationalCheck,
      total_score_check: totalScoreCheck,
    };
  
    const rationale = [
      `accuracy_improvement_rate:${accuracyImprovement}`,
      `implementation_complexity:${implementationComplexity}`,
      `operational_load:${operationalLoad}`,
    ].join(', ');
  
    return {
      is_approved: isApproved,
      priority_score: priorityScore,
      evaluation_basis: evaluationBasis,
      rationale: rationale,
    };
  }
  return { evaluateNutritionImprovementProposal };
})();
