/* AIVIC_FUNCTION_BUNDLE_START owner=evaluateImprovementProposals exports=evaluateImprovementProposals */
const __aivicBundle_88_evaluateImprovementProposals = (() => {
  function evaluateImprovementProposals(
    failurePatterns: any[],
    improvementProposals: any[]
  ): any[] {
    const results: any[] = [];
  
    for (const proposal of improvementProposals) {
      const matchingPattern = failurePatterns.find(
        (fp) => fp.pattern_id === proposal.failure_pattern_id
      );
  
      if (!matchingPattern) {
        continue;
      }
  
      const occurrenceNormalized = Math.min(matchingPattern.occurrence_count / 100, 1);
      const affectedUsersNormalized = Math.min(matchingPattern.affected_users / 200, 1);
      const severityWeight =
        matchingPattern.severity === 'critical'
          ? 1.0
          : matchingPattern.severity === 'high'
            ? 0.8
            : matchingPattern.severity === 'medium'
              ? 0.6
              : 0.4;
  
      const kpiContributionScore =
        proposal.kpi_contribution_factor * 100 +
        occurrenceNormalized * 10 +
        affectedUsersNormalized * 10 +
        severityWeight * 10;
  
      const implementationDifficultyScore = proposal.implementation_complexity * 100;
  
      const userImpactScore = proposal.user_impact_factor * 100;
  
      const totalPriorityScore = Math.min(
        (kpiContributionScore * userImpactScore) / implementationDifficultyScore,
        100
      );
  
      results.push({
        proposal_id: proposal.proposal_id,
        failure_pattern_id: proposal.failure_pattern_id,
        description: proposal.description,
        kpi_contribution_score: kpiContributionScore,
        implementation_difficulty_score: implementationDifficultyScore,
        user_impact_score: userImpactScore,
        total_priority_score: totalPriorityScore,
      });
    }
  
    return results;
  }
  return { evaluateImprovementProposals };
})();
