/* AIVIC_FUNCTION_BUNDLE_START owner=generateDifferentiationFeatureList exports=generateDifferentiationFeatureList */
const __aivicBundle_91_generateDifferentiationFeatureList = (() => {
  interface GenerateDifferentiationFeatureListInput {
    churnMetrics: {
      churnStageFrequency?: Record<string, number>;
      churnReasonFrequency?: Record<string, number>;
      painCategoryAggregation?: Record<string, {
        count: number;
        avgImportanceScore: number;
        affectedUserCount: number;
      }>;
      totalChurnCount?: number;
      overallChurnRate?: number;
      dominantPainCategory?: string;
      dominantChurnStage?: string;
    };
    competitiveBenchmark: {
      avgFeatureCount: number;
      avgUserSatisfactionScore: number;
    };
  }
  
  interface DifferentiationFeatureDetail {
    featureId: string;
    featureName: string;
    painCategory: string;
    priorityScore: number;
    quantitativeRationale: {
      churnFrequency: number;
      avgPainImportanceScore: number;
      affectedUserPercentage: number;
    };
    expectedImpact: {
      estimatedChurnReduction: number;
      estimatedSatisfactionGainScore: number;
    };
  }
  
  const generateDifferentiationFeatureListFeatureMapping: Record<string, { id: string; name: string; satisfactionGain: number }> = {
    input_complexity: {
      id: 'constraint_input_simplification',
      name: 'Constraint Input Simplification',
      satisfactionGain: 1.2,
    },
    preference_learning: {
      id: 'preference_learning_enhancement',
      name: 'Family Preference Learning Enhancement',
      satisfactionGain: 1.0,
    },
    nutrition_balance: {
      id: 'nutrition_algorithm_refinement',
      name: 'Nutrition Algorithm Refinement',
      satisfactionGain: 1.0,
    },
  };
  
   function generateDifferentiationFeatureList(
    input: GenerateDifferentiationFeatureListInput
  ): DifferentiationFeatureDetail[] {
    const { churnMetrics, competitiveBenchmark } = input;
  
    if (!churnMetrics || !churnMetrics.painCategoryAggregation) {
      return [];
    }
  
    if (!competitiveBenchmark || typeof competitiveBenchmark.avgFeatureCount !== 'number' || typeof competitiveBenchmark.avgUserSatisfactionScore !== 'number') {
      throw new Error('competitiveBenchmark with avgFeatureCount and avgUserSatisfactionScore is required');
    }
  
    const painCategoryAggregation = churnMetrics.painCategoryAggregation;
    const totalChurnCount = churnMetrics.totalChurnCount || 0;
    const competitorSatisfactionThreshold = competitiveBenchmark.avgUserSatisfactionScore;
  
    const features: DifferentiationFeatureDetail[] = [];
  
    for (const [painCategory, aggregation] of Object.entries(painCategoryAggregation)) {
      const mapping = generateDifferentiationFeatureListFeatureMapping[painCategory];
      if (!mapping) continue;
  
      const churnFrequency = aggregation.count;
      const avgPainImportanceScore = aggregation.avgImportanceScore;
      const affectedUserPercentage = totalChurnCount > 0
        ? (aggregation.affectedUserCount / totalChurnCount) * 100
        : 0;
  
      const churnImpactFactor = totalChurnCount > 0 ? churnFrequency / totalChurnCount : 0;
      const painIntensityFactor = avgPainImportanceScore / 10;
      const userReachFactor = affectedUserPercentage / 100;
      const competitorBenchmarkFactor = Math.max(0, (10 - competitorSatisfactionThreshold) / 10);
  
      const priorityScore = Math.min(
        100,
        (churnImpactFactor * 40 + painIntensityFactor * 35 + userReachFactor * 20 + competitorBenchmarkFactor * 5)
      );
  
      const estimatedChurnReduction = Math.min(
        0.99,
        churnImpactFactor * 0.3 + painIntensityFactor * 0.2
      );
  
      const estimatedSatisfactionGainScore = mapping.satisfactionGain;
  
      features.push({
        featureId: mapping.id,
        featureName: mapping.name,
        painCategory,
        priorityScore: Math.round(priorityScore * 10) / 10,
        quantitativeRationale: {
          churnFrequency,
          avgPainImportanceScore: Math.round(avgPainImportanceScore * 100) / 100,
          affectedUserPercentage: Math.round(affectedUserPercentage * 100) / 100,
        },
        expectedImpact: {
          estimatedChurnReduction: Math.round(estimatedChurnReduction * 100) / 100,
          estimatedSatisfactionGainScore,
        },
      });
    }
  
    features.sort((a, b) => b.priorityScore - a.priorityScore);
  
    return features;
  }
  return { generateDifferentiationFeatureList };
})();
