/* AIVIC_FUNCTION_BUNDLE_START owner=quantifyUserPainAndGenerateDifferentiationAxis exports=quantifyUserPainAndGenerateDifferentiationAxis */
const __aivicBundle_93_quantifyUserPainAndGenerateDifferentiationAxis = (() => {
  function quantifyUserPainAndGenerateDifferentiationAxis(input: {
    utilizationLogs: Array<any>;
    segmentId: string;
    analysisStartDate: Date;
    analysisEndDate: Date;
  }): any {
    if (!String(input.segmentId).trim()) {
      throw new Error("segmentId is required");
    }
  
    if (!input.utilizationLogs || input.utilizationLogs.length === 0) {
      return [];
    }
  
    const painFactorMap: Record<
      string,
      {
        categoryId: string;
        categoryName: string;
        frequency: number;
        impactScore: number;
      }
    > = {};
  
    for (const log of input.utilizationLogs) {
      const logTimestamp = new Date(log.timestamp);
      if (
        logTimestamp >= input.analysisStartDate &&
        logTimestamp <= input.analysisEndDate
      ) {
        const painFactorId = log.painFactorId || `pain_${log.stepName}`;
        const painFactorName = log.painFactorName || log.stepName || "Unknown";
  
        if (!painFactorMap[painFactorId]) {
          painFactorMap[painFactorId] = {
            categoryId: painFactorId,
            categoryName: painFactorName,
            frequency: 0,
            impactScore: 0,
          };
        }
  
        painFactorMap[painFactorId].frequency += 1;
        painFactorMap[painFactorId].impactScore += log.impactScore || 1;
      }
    }
  
    const painFactorCategories = Object.values(painFactorMap);
  
    const priorityMatrixItems = painFactorCategories.map((factor) => {
      const businessValue = Math.min(100, factor.frequency * 10);
      const implementationDifficulty = Math.max(
        20,
        Math.min(100, 50 + (factor.frequency % 30))
      );
      const userImpact = Math.min(100, factor.impactScore);
      const totalScore =
        businessValue * 0.4 +
        (100 - implementationDifficulty) * 0.3 +
        userImpact * 0.3;
  
      let priority: string;
      if (totalScore >= 70) {
        priority = "high";
      } else if (totalScore >= 40) {
        priority = "medium";
      } else {
        priority = "low";
      }
  
      return {
        painFactorId: factor.categoryId,
        painFactorName: factor.categoryName,
        businessValue,
        implementationDifficulty,
        userImpact,
        totalScore,
        priority,
      };
    });
  
    const highPriority = priorityMatrixItems.filter((p) => p.priority === "high");
    const mediumPriority = priorityMatrixItems.filter(
      (p) => p.priority === "medium"
    );
    const lowPriority = priorityMatrixItems.filter((p) => p.priority === "low");
  
    return {
      classificationStatus:
        painFactorCategories.length > 0 ? "success" : "insufficient_data",
      painFactorCategories,
      priorityMatrix: {
        highPriority,
        mediumPriority,
        lowPriority,
      },
      totalProcessedRecords: input.utilizationLogs.length,
      totalClassifiedPatterns: painFactorCategories.length,
      generatedAt: new Date().toISOString(),
    };
  }
  return { quantifyUserPainAndGenerateDifferentiationAxis };
})();
