const __aivicBundle_94_classifyRejectionReasonsAndAggregate = (() => {
  function classifyRejectionReasonsAndAggregate(
    rejectionHistoryRecords: Array<{
      historyId: number;
      mealPlanId: number;
      reasonText: string;
      createdAt: Date;
    }>,
    rejectionReasonCategories: Array<{
      categoryId: number;
      categoryName: string;
      keywords: string[];
    }>
  ) {
    const totalProcessedRecords = rejectionHistoryRecords.length;
    let totalClassifiedRecords = 0;
  
    const categoryAggregates: Array<{
      categoryId: number;
      categoryName: string;
      count: number;
      records: Array<{
        historyId: number;
        mealPlanId: number;
        reasonText: string;
        createdAt: Date;
      }>;
    }> = rejectionReasonCategories.map((category) => ({
      categoryId: category.categoryId,
      categoryName: category.categoryName,
      count: 0,
      records: [],
    }));
  
    const unclassifiedRecords: Array<{
      historyId: number;
      mealPlanId: number;
      reasonText: string;
      createdAt: Date;
    }> = [];
  
    for (const record of rejectionHistoryRecords) {
      const lowerReasonText = record.reasonText.toLowerCase();
      let classified = false;
  
      for (const category of rejectionReasonCategories) {
        const matchesKeyword = category.keywords.some((keyword) =>
          lowerReasonText.includes(keyword.toLowerCase())
        );
  
        if (matchesKeyword) {
          const aggregate = categoryAggregates.find(
            (agg) => agg.categoryId === category.categoryId
          );
          if (aggregate) {
            aggregate.count += 1;
            aggregate.records.push(record);
            totalClassifiedRecords += 1;
            classified = true;
            break;
          }
        }
      }
  
      if (!classified) {
        unclassifiedRecords.push(record);
      }
    }
  
    const classificationSuccessRate =
      totalProcessedRecords > 0
        ? Math.round((totalClassifiedRecords / totalProcessedRecords) * 100)
        : 0;
  
    const filteredAggregates = categoryAggregates.filter(
      (agg) => agg.count > 0 || agg.records.length > 0
    );
  
    return {
      totalProcessedRecords,
      totalClassifiedRecords,
      classificationSuccessRate,
      categoryAggregates: filteredAggregates,
      unclassifiedRecords,
    };
  }
  return { classifyRejectionReasonsAndAggregate };
})();
